                  projectRoot,
                  state: parseNativePortableState(run.state),
                  plans: nativeSdkCheckPlans(run.outputs['build.builder'].value),
                  managedArtifactRoot: path.join(projectRoot, 'docs'),
                };
                const before = await nativeCheckInputSnapshot(snapshotOptions);
                const result = await executor.execute(...args);
                const after = await nativeCheckInputSnapshot(snapshotOptions);
                const output = { ...(result.output as Record<string, RuntimeValue>) };
                // Reproduce the released receipt shape at the executor boundary, not by editing a Run.
                delete output.inputSnapshot;
                delete output.rawInput;
                delete output.candidateInputFingerprintGate;
                output.inputBefore = before.fingerprint;
                output.inputAfter = after.fingerprint;
                return { ...result, output };
              },
            },
      ),
      store: createNativeSdkStateStore(projectRoot),
      workflows: [workflow],
      transitionHandlers: [application.transitionHandler],
    });
    legacyRuntime = runtime;
    await runtime.start(start);
    await registerSdkChangeOwner(projectRoot, {
      schema: COMET_CHANGE_OWNER_SCHEMA,
      workflow: 'native',
      change: name,
      format: 'sdk',
      application: 'native',
      runId: name,
    });
  } else if (options.version === '3') {
    const materials = path.join(root, 'shape-materials');
    await fs.rename(change, materials);
    const created = await native([
      'new',
      name,
      '--isolation',
      'current',
      '--task',
      'Ship the candidate.',
    ]);
    expect(created.exitCode, created.stdout).toBe(0);
    await fs.mkdir(path.join(change, 'specs/example'), { recursive: true });
    for (const ref of ['brief.md', 'specs/example/spec.md'])
      await fs.copyFile(path.join(materials, ref), path.join(change, ref));
  } else await dispatch({ operation: 'start', ...start });
  const prepared = await native(['next', name]);
  expect(prepared.exitCode, prepared.stderr || prepared.stdout).toBe(0);
  let run = await dispatch({ operation: 'inspect', runId: name });
  expect(
    (
      await native([
        'next',
        name,
        '--confirmed',
        '--summary',
        'Confirm scope',
        '--expected-state-version',
        String(parseNativePortableState(run.state).state_version),
        '--expected-action',
        'confirm-shape',
        ...(options.supervisor ? ['--coordination-mode', 'multi-session'] : []),
      ])
    ).exitCode,
  ).toBe(0);
  run = await dispatch({ operation: 'inspect', runId: name });
  if (options.supervisor) {
    const childChecks = [
      {
        id: 'child-check',
        name: 'child-check',
        executable: process.execPath,
        argv: ['-e', 'process.exit(0)'],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      },
    ];
    const executors: Record<string, string> = {
      'supervisor.prepare': 'native-supervisor-prepare',
      'supervisor.child.prepare': 'native-supervisor-child-prepare',
      'supervisor.child.checks': 'comet-native-checks',
      'supervisor.child.integrate': 'native-supervisor-integrate',
      'supervisor.child.integration-checks': 'comet-native-checks',
      'supervisor.child.archive': 'native-supervisor-child-archive',
    };
    for (let step = 0; step < 24; step++) {
      const action = run.actions.find(({ status }) => status === 'pending')!;
      if (action.stepId === 'supervisor.parent.builder') break;
      if (action.stepId === 'supervisor.child.builder') {
        const activation = (action.input as { activation: { worktree: string; child: string } })
          .activation;
        await fs.writeFile(
          path.join(activation.worktree, `${activation.child}.txt`),
          'approved by child\n',
        );
        git(['add', `${activation.child}.txt`], activation.worktree);
        git(['commit', '-qm', 'child candidate'], activation.worktree);
        run = await record(
          action,
          {
            candidateCommit: git(['rev-parse', 'HEAD'], activation.worktree),
            verificationChecks: childChecks,
          },
          'child-builder',
        );
      } else if (action.stepId === 'supervisor.child.verifier') {
        const activation = (
          action.input as { activation: { candidateCommit: string; child: string } }
        ).activation;
        const blockedChild = Boolean(options.blockedChild && activation.child === 'right');
        run = await record(
          action,
          {
            candidateCommit: activation.candidateCommit,
            verdict: blockedChild ? 'blocked' : 'pass',
            evidence: {
              summary: 'Independently reviewed child',
              checks: ['child-check'],
              acceptance: [
                {
                  id: 'A1',
                  result: blockedChild ? 'blocked' : 'passed',
                  reason: 'Reviewed actual child candidate',
                },
              ],
            },
            integrationChecks: childChecks,
          },
          'child-verifier',
        );
        if (blockedChild) {
          useReleased = false;
          return {
            root,
            projectRoot,
            candidateRoot: (action.input as { activation: { worktree: string } }).activation
              .worktree,
            name,
            run,
            dispatch,
            native,
            record,
          };
        }
      } else {
        expect(executors[action.stepId], action.stepId).toBeDefined();
        run = await dispatch({
          operation: 'execute',
          runId: name,
          actionId: action.id,
          executorId: executors[action.stepId],
        });
      }
    }
    expect(run.actions.find(({ status }) => status === 'pending')?.stepId).toBe(
      'supervisor.parent.builder',
    );
  }
  const builder = run.actions.find(({ status }) => status === 'pending')!;
  const candidateRoot = options.supervisor
    ? (builder.input as { activation: { integrationWorktree: string } }).activation
        .integrationWorktree
    : projectRoot;
  run = await record(
    run.actions.find(({ status }) => status === 'pending')!,
    {
      summary: 'Implemented candidate',
      ...(options.nonGitEnvironment
        ? {}
        : { candidateCommit: git(['rev-parse', 'HEAD'], candidateRoot) }),
      addressedAcceptanceIds: ['A1'],
      acceptanceReview: fixtureAcceptanceReview(['A1']),
      checks: [],
      knownLimits: [],
      submittedAt: new Date().toISOString(),
      verificationChecks: options.verificationChecks ?? [
        {
          id: 'one-shot',
          name: 'one-shot',
          executable: process.execPath,
          argv: [
            '-e',
            options.version === '3'
              ? "const fs = require('node:fs'); fs.mkdirSync('dist', {recursive: true}); fs.appendFileSync('dist/check-count', 'once\\n')"
              : "require('node:fs').appendFileSync('check-count', 'once\\n')",
          ],
          cwdRef: '.',
          timeoutMs: 10000,
          repeatable: options.repeatableChecks ?? false,
          ...(options.version === '3' ? { outputs: ['dist/check-count'] } : {}),
        },
      ],
    },
    'builder',
  );
  run = await dispatch({
    operation: 'execute',
    runId: name,
    actionId: run.actions.find(({ status }) => status === 'pending')!.id,
    executorId: 'comet-native-checks',
  });
  const state = parseNativePortableState(run.state);
  if (options.claimVerifier) {
    const action = run.actions.find(({ status }) => status === 'pending')!;
    expect(action.stepId).toBe('verify.verifier');
    run = await dispatch({
      operation: 'claim',
      runId: name,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'native-host',
      sessionId: 'original-verifier',
      claimToken: 'original-verifier-claim',
    });
    return { root, projectRoot, candidateRoot, name, run, dispatch, native, record };
  }
  if (options.misclaimedVerifier) {
    const action = run.actions.find(({ status }) => status === 'pending')!;
    // 重现旧版已接受的错误领取；当前 Native 入口会在领取阶段拒绝它。
    const application = defineNativeWorkflowApplication();
    const legacy = createRuntime({
      ...application,
      workflows: [application.workflow],
      transitionHandlers: [application.transitionHandler],
      store: createFileRuntimeStore({
        rootDir: path.join(resolveWorkspaceRuntimeRootSync(projectRoot), 'sdk-runs', 'native'),
      }),
    });
    run = await legacy.claim({
      runId: name,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'native-host',
      sessionId: 'builder',
      claimToken: 'misclaimed-verifier',
    });
    return { root, projectRoot, candidateRoot, name, run, dispatch, native, record };
  }
  run = await record(
    run.actions.find(({ status }) => status === 'pending')!,
    {
      candidateId: state.builder_handoff!.candidate_id,
      verifierExecutionRef: 'blocked-verifier',
      response: {
        kind: 'final-result',
        result: {
          iteration: state.loop.iteration,
          attempt: state.loop.attempt,
          verdict: options.directPass ? 'pass' : 'blocked',
          acceptance: [
            {
              id: 'A1',
              result: options.directPass ? 'passed' : 'blocked',
              reason: options.directPass
                ? 'Independently verified the candidate.'
                : 'The requested independent model was unavailable.',
            },
          ],
          risks: [],
          summary: options.directPass
            ? 'All acceptance passed.'
            : 'Use the correct independent model, without changing requirements.',
        },
      },
    },
    'blocked-verifier',
  );
  useReleased = false;
  return { root, projectRoot, candidateRoot, name, run, dispatch, native, record };
}

type Alternative = { name: string; commandArgs: string[] };
async function alternatives(f: Awaited<ReturnType<typeof blockedFixture>>) {
  const status = await f.native(['status', f.name]);
  expect(status.exitCode, status.stderr).toBe(0);
  return JSON.parse(status.stdout!).data.continuation.commandAlternatives as Alternative[];
}
async function executeAlternative(action: Alternative) {
  return runNativeCli(
    action.commandArgs
      .slice(2)
      .map((argument) =>
        argument === '<summary>' ? 'The user explicitly chose this recovery.' : argument,
      ),
  );
}

function runPublicNative(projectRoot: string, ...args: string[]) {
  const result = spawnSync(
    process.execPath,
    [
      path.resolve(process.env.COMET_TEST_PACKAGE_ROOT ?? '.', 'bin/comet.js'),
      'native',
      ...args,
      '--json',
    ],
    { cwd: projectRoot, encoding: 'utf8', timeout: 30_000 },
  );
  if (result.error) throw result.error;
  return result;
}

async function archiveReadyFixture(
  options: {
    inProjectRequests?: boolean;
    deferredRevalidation?: boolean;
    dirtyEmbedded?: boolean;
    directPass?: boolean;
    generatedEmbedded?: boolean;
    verificationChecks?: NativeCheckPlan[];
    nonGitEnvironment?: boolean;
    bundleCommands?: boolean;
    inputExcludes?: string[];
    codeGraphCache?: boolean;
  } = {},
) {
  const f = await blockedFixture({
    bundleCommands: options.bundleCommands ?? true,
    inProjectRequests: options.inProjectRequests,
    dirtyEmbedded: options.dirtyEmbedded,
    directPass: options.directPass,
    generatedEmbedded: options.generatedEmbedded,
    verificationChecks: options.verificationChecks,
    nonGitEnvironment: options.nonGitEnvironment,
    inputExcludes: options.inputExcludes,
    codeGraphCache: options.codeGraphCache,
  });
  if (!options.directPass) {
    const resume = (await alternatives(f)).find(({ name }) => name === 'resolve-verifier-blocker')!;
    expect(
      (
        await f.native(
          resume.commandArgs
            .slice(2)
            .map((arg) => (arg === '<summary>' ? 'The independent verifier is available.' : arg)),
        )
      ).exitCode,
    ).toBe(0);
    const run = await f.dispatch({ operation: 'inspect', runId: f.name });
    const state = parseNativePortableState(run.state);
    await f.record(
      run.actions.findLast(({ status }) => status === 'pending')!,
      {
        candidateId: state.builder_handoff!.candidate_id,
        verifierExecutionRef: 'archive-verifier',
        response: {
          kind: 'final-result',
          result: {
            iteration: state.loop.iteration,
            attempt: state.loop.attempt,
            verdict: 'pass',
            acceptance: [
              {
                id: 'A1',
                result: 'passed',
                reason: 'Independently verified the retained candidate.',
              },
            ],
            risks: [],
            summary: 'All acceptance passed.',
          },
        },
      },
      'archive-verifier',
    );
  }
  expect((await f.native(['next', f.name])).exitCode).toBe(0);
  const data = JSON.parse((await f.native(['status', f.name])).stdout!).data;
  const approval = (data.continuation.commandAlternatives as Alternative[]).find(
    ({ name }) => name === 'accept-result',
  )!;
  if (options.deferredRevalidation) {
    const current = await f.dispatch({ operation: 'inspect', runId: f.name });
    const wait = current.waits.findLast(({ status }) => status === 'pending')!;
    await f.dispatch({
      operation: 'resolve-wait',
      runId: f.name,
      waitId: wait.id,
      proposalHash: wait.proposalHash,
      decisionId: 'approve-with-pending-revalidation',
      choice: 'approved',
    });
    return f;
  }
  expect(
    (
      await f.native(
        approval.commandArgs
          .slice(2)
          .map((arg) => (arg === '<summary>' ? 'Approve the verified result.' : arg)),
      )
    ).exitCode,
  ).toBe(0);
  return f;
}

async function finishRepairedCandidate(
  f: Awaited<ReturnType<typeof archiveReadyFixture>>,
  shape: string | null,
) {
  const after = await f.dispatch({ operation: 'inspect', runId: f.name });
  const live = JSON.parse((await f.native(['status', f.name])).stdout!).data;
  expect(live.recovery?.code).not.toBe('candidate-drift');
  await f.record(
    after.actions.findLast((action) => action.status === 'pending')!,
    {
      summary: 'Keep the user implementation revision.',
      addressedAcceptanceIds: ['A1'],
      acceptanceReview: fixtureAcceptanceReview(['A1']),
      checks: [],
      knownLimits: [],
      submittedAt: new Date().toISOString(),
      verificationChecks: [
        {
          id: 'revision-check',
          name: 'Verify the user revision',
          executable: process.execPath,
          argv: [
            '-e',
            "if (!require('node:fs').readFileSync('candidate.txt','utf8').includes('user implementation revision')) process.exit(1)",
          ],
          cwdRef: '.',
          timeoutMs: 10000,
          repeatable: true,
        },
      ],
    },
    'repair-builder',
  );
  expect((await f.native(['next', f.name])).exitCode).toBe(0);
  const checked = await f.dispatch({ operation: 'inspect', runId: f.name });
  const state = parseNativePortableState(checked.state);
  await f.record(
    checked.actions.findLast((action) => action.status === 'pending')!,
    {
      candidateId: state.builder_handoff!.candidate_id,
      verifierExecutionRef: 'repair-verifier',
      response: {
        kind: 'final-result',
        result: {
          iteration: state.loop.iteration,
          attempt: state.loop.attempt,
          verdict: 'pass',
          acceptance: [
            {
              id: 'A1',
              result: 'passed',
              reason: 'Independently verified the retained user revision.',
            },
          ],
          risks: [],
          summary: 'The successor candidate meets all acceptance.',
        },
      },
    },
    'repair-verifier',
  );
  expect((await f.native(['next', f.name])).exitCode).toBe(0);
  const approve = (await alternatives(f)).find((option) => option.name === 'accept-result')!;
  expect(
    (
      await f.native(
        approve.commandArgs
          .slice(2)
          .map((arg) => (arg === '<summary>' ? 'Approve the verified revision.' : arg)),
      )
    ).exitCode,
  ).toBe(0);
  const archived = await f.native(['archive', f.name]);
  expect(archived.exitCode, archived.stdout).toBe(0);
  expect((await f.dispatch({ operation: 'inspect', runId: f.name })).state).toMatchObject({
    archived: true,
    shape_confirmation_hash: shape,
  });
  expect(await fs.readFile(path.join(f.projectRoot, 'check-count'), 'utf8')).toBe('once\n');
}

describe('blocked Verifier recovery command contract', () => {
  it('resumes a claimed Verify in the original Run after input exclusions change', async () => {
    const f = await blockedFixture({
      version: '3',
      claimVerifier: true,
      repeatableChecks: true,
      nonGitEnvironment: true,
      inputExcludes: ['server/.env.development'],
    });
    const before = f.run as WorkflowRun;
    const state = parseNativePortableState(before.state);
    const action = before.actions.find(({ stepId }) => stepId === 'verify.verifier')!;
    const cli = (...args: string[]) => {
      const result = spawnSync(
        process.execPath,
        [
          path.resolve(process.env.COMET_TEST_PACKAGE_ROOT ?? '.', 'bin/comet.js'),
          ...args,
          '--json',
        ],
        { cwd: f.projectRoot, encoding: 'utf8', timeout: 30_000 },
      );
      if (result.error) throw result.error;
      return { exit: result.status, json: JSON.parse(result.stdout) };
    };
    const status = () => cli('native', 'status', f.name).json.agent.continuation;
    const config = path.join(f.projectRoot, '.comet/config.yaml');
    const original = await fs.readFile(config, 'utf8');
    expect(status().recovery?.request).toBeUndefined();
    const project = (await readProjectConfig(f.projectRoot))!;
    project.native.snapshot.exclude.push('client/.env.development');
    await writeProjectConfig(f.projectRoot, project);
    const updated = await fs.readFile(config, 'utf8');

    const observed = cli(
      'edit-review',
      'observe',
      'native',
      f.name,
      '--session',
      'original-verifier',
    );
    expect(observed.exit, observed.json.error).toBe(0);
    const recovery = observed.json.data.recovery;
    expect(recovery).toMatchObject({
      code: 'candidate-drift',
      owner: { actionId: action.id, sessionId: 'original-verifier' },
      preserved: {
        candidateId: state.builder_handoff!.candidate_id,
        shapeConfirmationHash: state.shape_confirmation_hash,
      },
    });
    expect(status().recovery).toMatchObject({ code: 'candidate-drift', request: recovery.request });
    expect((await f.dispatch({ operation: 'inspect', runId: f.name })).revision).toBe(
      before.revision,
    );

    const file = path.join(f.root, 'finish-verifier.json');
    const pass = (current: typeof state, verifierExecutionRef: string) => ({
      candidateId: current.builder_handoff!.candidate_id,
      verifierExecutionRef,
      response: {
        kind: 'final-result',
        result: {
          iteration: current.loop.iteration,
          attempt: current.loop.attempt,
          verdict: 'pass',
          acceptance: [{ id: 'A1', result: 'passed', reason: 'Verified the candidate.' }],
          requestReview: { result: 'aligned', reason: 'The candidate meets the approved request.' },
          risks: [],
          summary: 'Ready for user acceptance.',
        },
      },
    });
    const submit = (session: string) =>
      cli(
        ...recovery.recoveryArgs
          .slice(1)
          .filter((arg: string) => arg !== '--json')
          .map((arg: string) =>
            arg === '<actual-verifier-session>'
              ? session
              : arg === '<result-json-file>'
                ? file
                : arg,
          ),
      );
    await fs.writeFile(
      file,
      JSON.stringify({ status: 'succeeded', output: pass(state, 'original-verifier') }),
    );
    const stalePass = submit('original-verifier');
    expect(stalePass.exit).not.toBe(0);
    expect(stalePass.json.error.message).toMatch(/候选|输入|candidate|input/u);
    await fs.writeFile(file, JSON.stringify(recovery.request));
    expect(submit('other-session').exit).not.toBe(0);
    await fs.writeFile(config, original);
    expect(submit('original-verifier').exit).not.toBe(0);
    expect(
      (await f.dispatch({ operation: 'inspect', runId: f.name })).actions.find(
        (entry: RuntimeAction) => entry.id === action.id,
      )?.status,
    ).toBe('running');
    await fs.writeFile(config, updated);

    const settled = submit('original-verifier');
    expect(settled.exit, settled.json.error?.message).toBe(0);
    const repaired: WorkflowRun = await f.dispatch({ operation: 'inspect', runId: f.name });
    expect(repaired.runId).toBe(before.runId);
    expect(parseNativePortableState(repaired.state)).toMatchObject({
      phase: 'build',
      verification_result: 'pending',
      shape_confirmation_hash: state.shape_confirmation_hash,
    });
    expect(repaired.actions.find(({ id }) => id === action.id)?.outcome?.output).toEqual(
      recovery.request.output,
    );
    expect(repaired.actions.find(({ stepId }) => stepId === 'verify.checks')?.outcome).toEqual(
      before.actions.find(({ stepId }) => stepId === 'verify.checks')?.outcome,
    );
    expect(submit('original-verifier').exit).toBe(0);
    expect((await f.dispatch({ operation: 'inspect', runId: f.name })).revision).toBe(
      repaired.revision,
    );

    const builder = repaired.actions.find(({ status }) => status === 'pending')!;
    expect(builder.stepId).toBe('build.builder');
    const built = await f.record(
      builder,
      before.outputs['build.builder'].value,
      'successor-builder',
    );
    const check = built.actions.find(({ status }: RuntimeAction) => status === 'pending')!;
    const checked = await f.dispatch({
      operation: 'execute',
      runId: f.name,
      actionId: check.id,
      executorId: 'comet-native-checks',
    });
    const successor = parseNativePortableState(checked.state);
    expect(successor.phase).toBe('verify');
    expect(successor.builder_handoff!.candidate_id).not.toBe(state.builder_handoff!.candidate_id);
    const checks = checked.outputs['verify.checks'].value;
    const afterRef = checks.rawInput.afterRef;
    const snapshot = await readNativeRawInput(
      resolveWorkspaceRuntimeRootSync(f.projectRoot),
      path.posix.dirname(afterRef),
      afterRef,
    );
    expect(snapshot.files.map(({ path }) => path)).not.toContain('client/.env.development');
    expect(checks.checks[0]).not.toHaveProperty('reusedFrom');
    expect(await fs.readFile(path.join(f.projectRoot, 'dist/check-count'), 'utf8')).toBe(
      'once\nonce\n',
    );
    const verifier = checked.actions.find(({ status }: RuntimeAction) => status === 'pending')!;
    const reviewed = await f.record(
      verifier,
      pass(successor, 'successor-verifier'),
      'successor-verifier',
    );
    expect(parseNativePortableState(reviewed.state)).toMatchObject({
      phase: 'verify',
      status: 'await-user',
      verification_result: 'pass',
      shape_confirmation_hash: state.shape_confirmation_hash,
    });
    expect(
      reviewed.waits.some(
        (wait: { stepId: string; status: string }) =>
          wait.stepId === 'verify.confirm' && wait.status === 'pending',
      ),
    ).toBe(true);
  });

  it.each(['checkpoint', 'project input'] as const)(
    'checks a successor when a %s file appears after the check is claimed',
    async (kind) => {
      const f = await blockedFixture({
        version: '3',
        repeatableChecks: true,
        nonGitEnvironment: true,
      });
      const repair = (await alternatives(f)).find(({ name }) => name === 'revise-implementation')!;
      expect((await executeAlternative(repair)).exitCode).toBe(0);
      const build: WorkflowRun = await f.dispatch({ operation: 'inspect', runId: f.name });
      await fs.writeFile(path.join(f.projectRoot, 'AGENTS.md'), 'Read the project index.\n');
      const candidate: WorkflowRun = await f.record(
        build.actions.find(({ status }) => status === 'pending')!,
        f.run.outputs['build.builder'].value,
        'successor-builder',
      );
      const check = candidate.actions.find(({ status }) => status === 'pending')!;
      expect(check.stepId).toBe('verify.checks');

      const changeDir = path.join(f.projectRoot, 'docs/comet/changes', f.name);
      const checkpoint = path.join(changeDir, 'comet-state.yaml');
      const file = path.join(
        kind === 'checkpoint' ? changeDir : path.join(f.projectRoot, 'server'),
        '.comet-state.yaml.712d0e91-642d-4a73-ac11-7ccf0b0cc5c8.tmp',
      );
      const preload = path.join(f.root, 'checkpoint-overlap.mjs');
      // Keep a second checkpoint publication visible while the executor samples its input.
      await fs.writeFile(
        preload,
        `import { promises as fs } from 'node:fs';
const rename = fs.rename;
fs.rename = async (from, to) => {
  await rename(from, to);
  if (to === ${JSON.stringify(checkpoint)}) {
    fs.rename = rename;
    await fs.copyFile(to, ${JSON.stringify(file)});
  }
};
`,
      );
      const result = spawnSync(
        process.execPath,
        [
