          });
          expect(run.actions.at(-1)).toMatchObject({
            stepId: 'verify.verifier',
            status: 'pending',
          });
        }
      } finally {
        if (daemon?.listening) await new Promise<void>((resolve) => daemon!.close(() => resolve()));
      }
    },
  );

